pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmt, address sender, uint256 cashOutAmt) public {
        // 1. Restrict to admissible domain
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        vm.assume(sender != address(c));
        vm.assume(depositAmt >= c.MinDeposit());
        vm.assume(depositAmt <= type(uint256).max / 2);
        vm.assume(cashOutAmt <= type(uint256).max / 2);

        // 2. Setup and execute operations
        vm.deal(sender, depositAmt + cashOutAmt);
        vm.prank(sender);
        c.Deposit{value: depositAmt}();

        uint256 balAfterDeposit = c.balances(sender);
        if (cashOutAmt <= balAfterDeposit && balAfterDeposit > 0) {
            vm.prank(sender);
            try c.CashOut(cashOutAmt) {} catch {}
        }

        // 3. Compute total balances of all addresses that interacted (sender and address(0)).
        // This is necessary because the mutant credits address(0).
        uint256 totalBal = c.balances(sender) + c.balances(address(0));
        uint256 contractBal = address(c).balance;

        // The invariant: sum of balances of all addresses that could have received credit equals contract balance.
        // Since only sender deposits and address(0) might get credit in the mutant, we check equality.
        // In the correct contract, address(0) balance is always 0, so totalBal == c.balances(sender) == contractBal.
        // In the mutant, address(0) gets the deposit, so sender balance stays 0, and totalBal is non-zero but mismatched with contractBal because deposits credited to address(0) but contract balance still increases.
        assertEq(totalBal, contractBal, "invariant violated: sum of balances != contract balance");
    }
}

